import { designRoadJunctions } from './road-junctions.mjs';
import { metricRoads } from './road-geometry.mjs';

/** Bounded terrain-aware side streets. Geometry is saved, never regenerated by
 * the viewer. A failed grade or wet path stays a rejected candidate. */
export function extendVillageRoads({roads,groundAt,waterAt,maxBranches=2,maxSlope=.12}){
 if(typeof groundAt!=='function'||typeof waterAt!=='function')throw new TypeError('Terrain and water samplers are required');
 if(!Array.isArray(roads)||roads.length!==1||!Number.isSafeInteger(maxBranches)||maxBranches<0||maxBranches>2||!Number.isFinite(maxSlope)||maxSlope<=0||maxSlope>.25)throw new RangeError('Invalid village road budget');
 const main=metricRoads(roads)[0],candidates=[],rejected=[];
 for(const fraction of[.2,.5,.8])for(const side of[-1,1]){
  const station=main.lengthM*fraction,root=main.at(station),near=main.at(Math.min(main.lengthM,station+1)),dx=near.xM-root.xM,dy=near.yM-root.yM,len=Math.hypot(dx,dy),direction={xM:-side*dy/len,yM:side*dx/len},id=`${main.id}/branch:${fraction}:${side}`;
  if(root.structureKind==='bridge-deck'||!Number.isFinite(direction.xM)){rejected.push({id,reason:'bridge-or-degenerate-junction'});continue;}
  const samples=Array.from({length:7},(_,i)=>{const distanceM=i*20,xM=root.xM+direction.xM*distanceM,yM=root.yM+direction.yM*distanceM;return{xM,yM,distanceM,roadElevationM:i?groundAt(xM,yM)+.12:root.roadElevationM,structureKind:'fill',segmentKind:'fill'};});
  let wet=false,unknown=false,cost=0,steep=false;
  for(let d=0;d<=120;d+=2)for(const across of[-2,0,2]){const x=root.xM+direction.xM*d-direction.yM*across,y=root.yM+direction.yM*d+direction.xM*across,sample=waterAt(x,y);unknown||=sample.waterDepthM==null;wet||=sample.waterDepthM>0;}
  for(let i=0;i<samples.length;i++){const p=samples[i];if(waterAt(p.xM,p.yM).waterDepthM>0)wet=true;if(i){const grade=Math.abs(p.roadElevationM-samples[i-1].roadElevationM)/20;cost+=grade;steep||=grade>maxSlope/1.5;}}
  if(wet||unknown||steep){rejected.push({id,reason:unknown?'unknown-water':wet?'wet-route':'steep-route'});continue;}
  candidates.push({road:{roadId:id,halfWidthM:2,samples},cost,root,direction});
 }
 candidates.sort((a,b)=>a.cost-b.cost||(a.road.roadId<b.road.roadId?-1:a.road.roadId>b.road.roadId?1:0));
 let result={roads,junctions:[]};const branches=[];
 for(const candidate of candidates){if(branches.length===maxBranches)break;
  try{const planned=designRoadJunctions([...result.roads,candidate.road],{maxSlope});result=planned;branches.push({roadId:candidate.road.roadId,root:candidate.root,direction:candidate.direction,lengthM:120});}
  catch(error){if(!(error instanceof RangeError))throw error;rejected.push({id:candidate.road.roadId,reason:'junction-grade-or-overlap',detail:error.message});}
 }
 return{roads:result.roads,junctions:result.junctions,branches,diagnostics:{method:'terrain-side-streets@1',candidates:6,accepted:branches.length,rejected,maxSlope,waterProbeStepM:2,scope:'local straight side streets with common-height junctions; no inter-settlement road network'}};
}
